import ast
from pathlib import Path

def test_billing_does_not_import_catalog_models():
    for path in Path("billing").rglob("*.py"):
        tree = ast.parse(path.read_text())
        for node in ast.walk(tree):
            if isinstance(node, ast.ImportFrom) and node.module:
                assert not node.module.startswith("catalog.models"), path

