from django.db import transaction

@transaction.atomic
def place_order(*, customer, sku, quantity):
    product = Product.objects.select_for_update().get(sku=sku)
    if product.stock < quantity:
        raise OutOfStock(sku)
    product.stock -= quantity
    product.save(update_fields=["stock"])
    return Order.objects.create(customer=customer, sku=sku, quantity=quantity)

# interface/views.py
def order_create(request):
    form = OrderForm(request.POST or None)
    if request.method == "POST" and form.is_valid():
        try:
            order = place_order(customer=request.user, **form.cleaned_data)
        except OutOfStock as exc:
            form.add_error("sku", f"Only {exc.available} left.")
        else:
            return redirect("order-detail", pk=order.pk)
    return render(request, "orders/create.html", {"form": form})

