import json
from django.http import HttpResponse, HttpResponseBadRequest
from django.views.decorators.csrf import csrf_exempt

@csrf_exempt
def provider_webhook(request):
    payload = request.body
    signature = request.headers.get("X-Provider-Signature", "")
    if not gateway.verify(payload, signature):
        return HttpResponseBadRequest("bad signature")
    event = json.loads(payload)
    if not ProcessedEvent.objects.filter(event_id=event["id"]).exists():
        process_provider_event.delay(event)
    return HttpResponse(status=200)

class Payment(models.Model):
    status = models.CharField(max_length=20, default="pending")
    provider_id = models.CharField(max_length=120, blank=True)
    amount = models.DecimalField(max_digits=10, decimal_places=2)

    def transition(self, new_status):
        allowed = {
            "pending": {"authorized", "failed"},
            "authorized": {"captured", "voided"},
            "captured": {"refunded", "disputed"},
        }
        if new_status not in allowed.get(self.status, set()):
            raise ValueError(f"Invalid transition {self.status} -> {new_status}")
        self.status = new_status
        self.save(update_fields=["status"])

def reconcile(day):
    provider_events = gateway.list_events(day)
    for event in provider_events:
        apply_event_if_new(event)
    local = Payment.objects.filter(created_at__date=day)
    return compare_totals(local, provider_events)

import csv
from django.http import StreamingHttpResponse

class Echo:
    def write(self, value):
        return value

def export_orders(request):
    writer = csv.writer(Echo())
    queryset = Order.objects.filter(owner=request.user).select_related("customer")

    def rows():
        yield writer.writerow(["id", "customer", "total", "status"])
        for order in queryset.iterator(chunk_size=500):
            yield writer.writerow([order.pk, order.customer.email, order.total, order.status])

    response = StreamingHttpResponse(rows(), content_type="text/csv")
    response["Content-Disposition"] = 'attachment; filename="orders.csv"'
    return response
